#!/usr/bin/env node
/**
 * Guards against `public/mockServiceWorker.js` drifting from the installed MSW.
 *
 * The worker script is generated by `msw init` and committed to the repo, so it
 * does not update when the dependency does. A stale worker fails MSW's own
 * integrity check at runtime and silently disables mocking — which, now that
 * the hosted demo depends on MSW, would take the whole demo down.
 *
 * Wired into the `lint` script and CI. Fix a failure with:
 *   vp exec msw init public --save
 */
import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { consola } from 'consola'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..')
const workerPath = resolve(root, 'public/mockServiceWorker.js')
const mswPackagePath = resolve(root, 'node_modules/msw/package.json')

const logger = consola.withTag('msw-worker')

function fail(message) {
  logger.error(message)
  process.exit(1)
}

let workerSource
try {
  workerSource = readFileSync(workerPath, 'utf8')
} catch {
  fail(
    `Missing ${workerPath}.\n` +
      `MSW cannot intercept requests without it. Generate it with:\n` +
      `  vp exec msw init public --save`,
  )
}

let installedVersion
try {
  installedVersion = JSON.parse(readFileSync(mswPackagePath, 'utf8')).version
} catch {
  fail(`Could not read ${mswPackagePath}. Run \`vp install\` first.`)
}

const match = workerSource.match(/PACKAGE_VERSION\s*=\s*['"]([^'"]+)['"]/)
if (!match) {
  fail(
    `Could not find PACKAGE_VERSION in ${workerPath}.\n` +
      `The file may be corrupt — regenerate it with \`vp exec msw init public --save\`.`,
  )
}

const workerVersion = match[1]

if (workerVersion !== installedVersion) {
  fail(
    `Service worker is out of date: public/mockServiceWorker.js is ${workerVersion}, ` +
      `but msw ${installedVersion} is installed.\n` +
      `Regenerate and commit it:\n` +
      `  vp exec msw init public --save`,
  )
}

logger.success(`mockServiceWorker.js matches msw ${installedVersion}.`)
